-- SmartPortfolio v1.0.0 / MySQL 8.0+ / utf8mb4
SET NAMES utf8mb4; SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,email VARCHAR(191) NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','admin') NOT NULL DEFAULT 'admin',is_active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_name VARCHAR(191) NOT NULL,profession VARCHAR(191),company VARCHAR(191),short_intro TEXT,full_bio LONGTEXT,profile_image VARCHAR(500),cover_image VARCHAR(500),email VARCHAR(191),phone VARCHAR(60),whatsapp VARCHAR(60),address VARCHAR(255),location VARCHAR(191),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS website_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_title VARCHAR(191) NOT NULL,site_tagline VARCHAR(255),logo VARCHAR(500),favicon VARCHAR(500),domain VARCHAR(255),footer_text TEXT,copyright_text VARCHAR(255),developer_credit VARCHAR(255),resume_button_text VARCHAR(100) DEFAULT 'Download CV',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS theme_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,preset VARCHAR(80) DEFAULT 'Corporate Blue',mode ENUM('light','dark','system') DEFAULT 'system',primary_color VARCHAR(20) DEFAULT '#2563eb',secondary_color VARCHAR(20) DEFAULT '#0f172a',accent_color VARCHAR(20) DEFAULT '#14b8a6',background_color VARCHAR(20) DEFAULT '#f8fafc',surface_color VARCHAR(20) DEFAULT '#ffffff',heading_color VARCHAR(20) DEFAULT '#0f172a',text_color VARCHAR(20) DEFAULT '#475569',link_color VARCHAR(20) DEFAULT '#2563eb',navbar_bg VARCHAR(20) DEFAULT '#ffffff',navbar_text VARCHAR(20) DEFAULT '#0f172a',footer_bg VARCHAR(20) DEFAULT '#0f172a',footer_text VARCHAR(20) DEFAULT '#e2e8f0',button_color VARCHAR(20) DEFAULT '#2563eb',border_color VARCHAR(20) DEFAULT '#e2e8f0',body_font VARCHAR(100) DEFAULT 'Inter',heading_font VARCHAR(100) DEFAULT 'Inter',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS theme_presets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,tokens JSON NOT NULL,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS layout_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,width_mode ENUM('boxed','full') DEFAULT 'full',container_width INT DEFAULT 1180,sticky_navbar TINYINT(1) DEFAULT 1,hero_layout VARCHAR(50) DEFAULT 'split',section_spacing INT DEFAULT 96,card_radius INT DEFAULT 18,button_radius INT DEFAULT 10,card_style VARCHAR(50) DEFAULT 'elevated',footer_style VARCHAR(50) DEFAULT 'columns',animation_level ENUM('none','subtle','full') DEFAULT 'subtle',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS seo_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meta_title VARCHAR(191),meta_description VARCHAR(320),keywords TEXT,canonical_domain VARCHAR(255),og_image VARCHAR(500),analytics_id VARCHAR(100),indexing_enabled TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS menus (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,label VARCHAR(100) NOT NULL,target_type ENUM('section','page','url') DEFAULT 'section',target VARCHAR(500) NOT NULL,icon VARCHAR(100),new_tab TINYINT(1) DEFAULT 0,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(active,display_order)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,section_key VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(191) NOT NULL,subtitle VARCHAR(255),layout_style VARCHAR(80),icon VARCHAR(100),presentation JSON NULL,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS about (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(191),subtitle VARCHAR(255),content LONGTEXT,image VARCHAR(500),facts JSON NULL,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS experiences (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization VARCHAR(191) NOT NULL,designation VARCHAR(191) NOT NULL,department VARCHAR(191),employment_type VARCHAR(80),start_date DATE,end_date DATE,current_flag TINYINT(1) DEFAULT 0,location VARCHAR(191),responsibilities LONGTEXT,achievements LONGTEXT,logo VARCHAR(500),url VARCHAR(500),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS educations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,degree VARCHAR(191) NOT NULL,subject VARCHAR(191),institute VARCHAR(191) NOT NULL,result VARCHAR(100),start_date DATE,end_date DATE,description TEXT,logo VARCHAR(500),url VARCHAR(500),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skill_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,slug VARCHAR(140) NOT NULL UNIQUE,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS skills (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,level VARCHAR(50),percentage TINYINT UNSIGNED DEFAULT 0,icon VARCHAR(100),description TEXT,display_style VARCHAR(50) DEFAULT 'bar',display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES skill_categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS certifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(191) NOT NULL,organization VARCHAR(191),issue_date DATE,expiry_date DATE,credential_id VARCHAR(191),credential_url VARCHAR(500),description TEXT,image VARCHAR(500),document VARCHAR(500),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,slug VARCHAR(140) NOT NULL UNIQUE,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,title VARCHAR(191) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,thumbnail VARCHAR(500),excerpt TEXT,details LONGTEXT,client VARCHAR(191),project_date DATE,technologies JSON NULL,demo_url VARCHAR(500),external_url VARCHAR(500),video_url VARCHAR(500),featured TINYINT(1) DEFAULT 0,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES project_categories(id) ON DELETE SET NULL,INDEX(active,featured,display_order)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS project_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,image_path VARCHAR(500) NOT NULL,alt_text VARCHAR(191),display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(191) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,icon VARCHAR(100),image VARCHAR(500),short_description TEXT,description LONGTEXT,price VARCHAR(100),cta_label VARCHAR(100),cta_url VARCHAR(500),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS achievements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(191) NOT NULL,organization VARCHAR(191),achievement_date DATE,description TEXT,image VARCHAR(500),certificate VARCHAR(500),url VARCHAR(500),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS testimonials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_name VARCHAR(191) NOT NULL,designation VARCHAR(191),organization VARCHAR(191),photo VARCHAR(500),rating TINYINT UNSIGNED DEFAULT 5,testimonial TEXT NOT NULL,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(191) NOT NULL,logo VARCHAR(500),url VARCHAR(500),description TEXT,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,slug VARCHAR(140) NOT NULL UNIQUE,description TEXT,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,title VARCHAR(191) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,excerpt TEXT,content LONGTEXT NOT NULL,featured_image VARCHAR(500),author VARCHAR(191),publish_date DATETIME,status ENUM('draft','published','archived') DEFAULT 'draft',featured TINYINT(1) DEFAULT 0,seo_title VARCHAR(191),seo_description VARCHAR(320),seo_keywords TEXT,view_count BIGINT UNSIGNED DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES post_categories(id) ON DELETE SET NULL,FULLTEXT KEY ft_posts(title,excerpt,content),INDEX(status,publish_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,slug VARCHAR(120) NOT NULL UNIQUE,display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_tag_mapping (post_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(post_id,tag_id),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS post_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_id BIGINT UNSIGNED NOT NULL,image_path VARCHAR(500) NOT NULL,alt_text VARCHAR(191),display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS custom_pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(191) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,subtitle VARCHAR(255),banner VARCHAR(500),content LONGTEXT,status ENUM('draft','published','archived') DEFAULT 'draft',menu_visible TINYINT(1) DEFAULT 0,display_order INT DEFAULT 0,seo_title VARCHAR(191),seo_description VARCHAR(320),seo_keywords TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS custom_sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(191) NOT NULL,subtitle VARCHAR(255),rich_text LONGTEXT,image VARCHAR(500),icon VARCHAR(100),cta_label VARCHAR(100),cta_url VARCHAR(500),layout_style VARCHAR(80),background VARCHAR(100),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS custom_section_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,section_id BIGINT UNSIGNED NOT NULL,title VARCHAR(191),subtitle VARCHAR(255),description TEXT,image VARCHAR(500),icon VARCHAR(100),url VARCHAR(500),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(section_id) REFERENCES custom_sections(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,original_name VARCHAR(255) NOT NULL,file_name VARCHAR(255) NOT NULL UNIQUE,file_path VARCHAR(500) NOT NULL UNIQUE,mime_type VARCHAR(100) NOT NULL,file_size BIGINT UNSIGNED NOT NULL,alt_text VARCHAR(191),title VARCHAR(191),uploaded_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(uploaded_by) REFERENCES admin_users(id) ON DELETE SET NULL,INDEX(original_name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resumes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(191) NOT NULL,file_path VARCHAR(500) NOT NULL,button_text VARCHAR(100) DEFAULT 'Download CV',version VARCHAR(50),active TINYINT(1) DEFAULT 1,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS social_links (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,platform VARCHAR(80) NOT NULL,label VARCHAR(100),url VARCHAR(500) NOT NULL,icon VARCHAR(100),display_order INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(191) NOT NULL,email VARCHAR(191) NOT NULL,phone VARCHAR(60),subject VARCHAR(255) NOT NULL,message TEXT NOT NULL,is_read TINYINT(1) DEFAULT 0,read_at DATETIME NULL,ip_address VARCHAR(64),user_agent VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(is_read,created_at),INDEX(email)) ENGINE=InnoDB;
SET FOREIGN_KEY_CHECKS=1;
